#!/usr/bin/env python3
"""Regenerate icall_POSIX.c (FreeRTOS ICall for the CC26x2x7 BLE5 ROM stack).

Usage:  python third_party/ti_ble5stack_freertos/make_icall_port.py

Reads TI's source/ti/ble5stack/common/cc26xx/freertos/icall_POSIX.c from the
installed SDK, applies the changes below and writes icall_POSIX.c plus
icall_POSIX.c.patch (for review) next to this script. Every change is taken
from TI's current TI-RTOS ICall (source/ti/ble5stack/icall/src/icall.c), which
is what TI's basic_ble for CC2652R7 uses. Rerun after upgrading the SDK; the
script fails loudly if TI's file changed in a way the edits no longer match.
"""

import difflib
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent.parent / "tools"))
import ti_paths  # noqa: E402

SRC_REL = "source/ti/ble5stack/common/cc26xx/freertos/icall_POSIX.c"


def replace(s: str, old: str, new: str, count: int = 1) -> str:
    found = s.count(old)
    if found != count:
        raise SystemExit(f"expected {count} match(es), found {found}:\n{old[:200]}")
    return s.replace(old, new)


def port(s: str) -> str:
    header = (
        "/*\n"
        " * FreeRTOS ICall for the CC26x2x7 BLE5 (ROM) stack, generated by\n"
        " * third_party/ti_ble5stack_freertos/make_icall_port.py from TI's\n"
        f" * {SRC_REL}.\n"
        " * Changes (see icall_POSIX.c.patch), all following TI's TI-RTOS\n"
        " * source/ti/ble5stack/icall/src/icall.c:\n"
        " *  - ICALL_NO_APP_EVENTS: ICall_registerAppCback() and direct app\n"
        " *    callbacks in ICall_send()/ICall_primSend().\n"
        " *  - ICALL_Task_disable/restore: no-op before the scheduler starts.\n"
        " *  - Heap: with HEAPMGR_CONFIG use heapmgr (rtos_heaposal.h) like\n"
        " *    icall.c instead of malloc, initialized in ICall_init(); ICall_heapCSState always declared;\n"
        " *    XDC types for the unused TI-RTOS HeapCallback glue.\n"
        " * DO NOT EDIT: change the script instead.\n"
        " */\n"
    )

    # 1. Entity table: store the app callback.
    s = replace(s, """typedef struct _icall_entity_entry_t
{
  ICall_ServiceEnum service;
  ICall_TaskEntry *task;
  ICall_ServiceFunc fn;
} ICall_entityEntry;""", """typedef struct _icall_entity_entry_t
{
  ICall_ServiceEnum service;
  ICall_TaskEntry *task;
  ICall_ServiceFunc fn;
#ifdef ICALL_NO_APP_EVENTS
  appCallback_t appCallback;
#endif
} ICall_entityEntry;""")

    # 2. Clear the callback wherever an entity entry is allocated.
    s = replace(s, """      ICall_entities[i].fn = NULL;""", """      ICall_entities[i].fn = NULL;
#ifdef ICALL_NO_APP_EVENTS
      ICall_entities[i].appCallback = NULL;
#endif""", count=2)

    # 3. ICall_primSend (only built without ICALL_JT).
    s = replace(s, """  hdr->format = args->format;
  ICall_msgEnqueue(&ICall_entities[args->dest.entityId].task->queue, args->msg);""",
                """  hdr->format = args->format;
#ifdef ICALL_NO_APP_EVENTS
  // for applications, call direct to callback without enqueue/event_pend/dequeue
  if (ICall_entities[args->dest.entityId].service == ICALL_SERVICE_CLASS_APPLICATION)
  {
    if (ICall_entities[args->dest.entityId].appCallback != NULL)
    {
      uint8_t safeToDealloc = ICall_entities[args->dest.entityId].appCallback(0 /*event*/, (uint8_t *)args->msg);
      if (args->msg && safeToDealloc)
      {
        ICall_freeMsg(args->msg);
      }
    }
    return ICALL_ERRNO_SUCCESS;
  }
#endif // ICALL_NO_APP_EVENTS
  ICall_msgEnqueue(&ICall_entities[args->dest.entityId].task->queue, args->msg);""")

    # 4. ICall_send.
    s = replace(s, """  hdr->format = format;

  ICall_msgEnqueue(&ICall_entities[dest].task->queue, msg);
/* 0x80000000 is an internal event number */""", """  hdr->format = format;

#ifdef ICALL_NO_APP_EVENTS
  // for applications, call direct to callback without enqueue/event_pend/dequeue
  if (ICall_entities[dest].service == ICALL_SERVICE_CLASS_APPLICATION)
  {
    if (ICall_entities[dest].appCallback != NULL)
    {
      uint8_t safeToDealloc = ICall_entities[dest].appCallback(0 /*event*/, (uint8_t *)msg);
      if (msg && safeToDealloc)
      {
        ICall_freeMsg(msg);
      }
    }
    return (ICALL_ERRNO_SUCCESS);
  }
#endif // ICALL_NO_APP_EVENTS
  ICall_msgEnqueue(&ICall_entities[dest].task->queue, msg);
/* 0x80000000 is an internal event number */""")

    # 5. Heap: declare the lock state for every HEAPMGR_CONFIG (as icall.c
    #    does) and give the unused TI-RTOS HeapCallback glue its XDC types.
    s = replace(s, """#if defined(HEAPMGR_CONFIG) && ((HEAPMGR_CONFIG == 0) || (HEAPMGR_CONFIG == 0x80))
#include <rtos_heaposal.h>""", """static ICall_CSState ICall_heapCSState;
#ifdef FREERTOS
/* rtos_heaposal.h ends with TI-RTOS HeapCallback glue (osalHeap*Fxn) that
 * uses XDC types. Those functions are not used on FreeRTOS. */
typedef uintptr_t UArg;
typedef void *Ptr;
typedef size_t SizeT;
typedef unsigned char Bool;
typedef struct Memory_Stats Memory_Stats;
#endif
#if defined(HEAPMGR_CONFIG) && ((HEAPMGR_CONFIG == 0) || (HEAPMGR_CONFIG == 0x80))
#include <rtos_heaposal.h>""")
    s = replace(s, """#else
static ICall_CSState ICall_heapCSState;
#include <rtos_heaposal.h>""", """#else
#include <rtos_heaposal.h>""")

    # 5b. The legacy port's FreeRTOS heap (plain malloc) is only for builds
    #     without heapmgr. With HEAPMGR_CONFIG (as TI's TI-RTOS build and this
    #     repo use), rtos_heaposal.h provides these functions, sized from the
    #     linker symbols heapStart/heapEnd.
    s = replace(s, """#ifdef FREERTOS

/**
 * Allocates a memory block.
 * @param size   size of the block in bytes.
 * @return address of the allocated memory block or NULL
 *         if allocation fails.
 */

void *ICall_heapMalloc(uint32_t size)""", """#if defined(FREERTOS) && !defined(HEAPMGR_CONFIG)

/**
 * Allocates a memory block.
 * @param size   size of the block in bytes.
 * @return address of the allocated memory block or NULL
 *         if allocation fails.
 */

void *ICall_heapMalloc(uint32_t size)""")

    # 7. ICall_createRemoteTasks() runs from main(), before the scheduler.
    #    ICALL_Task_disable/restore then call pthread_self() with no running
    #    task, which reaches xTaskGetApplicationTaskTag(NULL) and fails
    #    configASSERT (TI's FreeRTOSConfig.h leaves configASSERT undefined,
    #    so TI's build silently continues with a NULL task handle). Before
    #    the scheduler starts no other task can run, so there is nothing to
    #    lock: return early.
    s = replace(s, """void ICALL_Task_disable(struct sched_param *OriginalParam)
{
""", """void ICALL_Task_disable(struct sched_param *OriginalParam)
{
#ifdef FREERTOS
    if (xTaskGetSchedulerState() == taskSCHEDULER_NOT_STARTED)
    {
        return; /* No task running yet: nothing to lock. */
    }
#endif
""")
    s = replace(s, """void  ICALL_Task_restore(struct sched_param *OriginalParam)
{
""", """void  ICALL_Task_restore(struct sched_param *OriginalParam)
{
#ifdef FREERTOS
    if (xTaskGetSchedulerState() == taskSCHEDULER_NOT_STARTED)
    {
        return; /* Matches ICALL_Task_disable(). */
    }
#endif
""")

    # 8. ICall_init() skips ICall_heapInit() on FreeRTOS because the legacy
    #    port used malloc. With heapmgr (change 5b) the heap must be
    #    initialized here, exactly as ble5stack/icall/src/icall.c does.
    s = replace(s, """  /* Initialize heap */
#ifndef FREERTOS
  ICall_heapInit();
#endif //FREERTOS""", """  /* Initialize heap */
#if !defined(FREERTOS) || defined(HEAPMGR_CONFIG)
  ICall_heapInit();
#endif""")

    # 6. ICall_registerAppCback, from icall.c (including the *selfEntity
    #    assignment that ble5stack_flash's POSIX ICall is missing).
    s += """
#ifdef ICALL_NO_APP_EVENTS
/* Ported from ble5stack/icall/src/icall.c (TI-RTOS version). */
ICall_Errno ICall_registerAppCback(uint8_t *selfEntity, appCallback_t appCallback)
{
  ICall_EntityID   localSelfEntity;
  ICall_SyncHandle localSyncEvent; // no use
  ICall_Errno status;

  // ******************************************************************
  // N0 STACK API CALLS CAN OCCUR BEFORE THIS CALL TO ICall_registerApp
  // ******************************************************************
  // Register the current thread as an ICall dispatcher application
  // so that the application can send and receive messages.
  status = ICall_registerApp(&localSelfEntity, &localSyncEvent);

  // Application should use the task entity ID
  *selfEntity = localSelfEntity;

  // Save app callback to be used instead of enqueue/event_pend/dequeue
  ICall_entities[localSelfEntity].appCallback = appCallback;

  return status;
}
#endif // ICALL_NO_APP_EVENTS
"""
    return header + s


def main() -> int:
    src = ti_paths.find_sdk() / SRC_REL
    original = src.read_text(encoding="utf-8")
    ported = port(original)
    (HERE / "icall_POSIX.c").write_text(ported, encoding="utf-8")
    diff = difflib.unified_diff(
        original.splitlines(keepends=True), ported.splitlines(keepends=True),
        fromfile=f"{SRC_REL} (TI SDK)", tofile="icall_POSIX.c")
    (HERE / "icall_POSIX.c.patch").write_text("".join(diff), encoding="utf-8")
    print("wrote icall_POSIX.c and icall_POSIX.c.patch")
    return 0


if __name__ == "__main__":
    sys.exit(main())
